const facturas = $('17 - Consulta Facturas Pendientes').all();
const chat_id = $('Inicio').item.json.chat_id;

const inline_keyboard = facturas.map(f => ([{
  text: `${f.json.numero_factura} - $${f.json.saldo_pendiente} (${f.json.bucket_aging})`,
  callback_data: `factura:${f.json.factura_id}`
}]));

return {
  json: {
    chat_id: chat_id,
    texto: facturas.length > 0
      ? 'Selecciona la factura que deseas pagar:'
      : 'No tienes facturas pendientes.',
    botones: JSON.stringify({ inline_keyboard })
  }
};

const mensaje = $('Inicio').item.json.mensaje_usuario;
const factura_id = mensaje.replace('factura:', '');
const chat_id = $('Inicio').item.json.chat_id;

return {
  json: {
    chat_id: chat_id,
    factura_id: factura_id
  }
};

const texto = $('Inicio').item.json.mensaje_usuario;
const monto = parseFloat(texto);
const esValido = !isNaN(monto) && monto > 0 && /^\d+(\.\d{1,2})?$/.test(texto.trim());

return {
  json: {
    monto_valido: esValido,
    monto: esValido ? monto : null
  }
};

const mensaje = $('Inicio').item.json.mensaje_usuario;
const esMetodoValido = mensaje.startsWith('metodo:');
const metodo = esMetodoValido ? mensaje.replace('metodo:', '') : null;

return {
  json: {
    metodo_valido: esMetodoValido,
    metodo: metodo
  }
};

const datos = JSON.parse($('Inicio').item.json.datos_temporales);
const signedPath = $json.signedURL;
const urlCompleta = `https://__SUPABASE_PROJECT_REF__.supabase.co/storage/v1${signedPath}`;
const cobroId = $('45 - Guarda Cobro').item.json.id;
const emailAnalista = $('46c - Consulta Email Analista Cobros').item.json.valor;

return {
  json: {
    numero_factura: datos.numero_factura,
    monto: datos.monto,
    metodo_pago: datos.metodo_pago,
    referencia: datos.referencia,
    url_comprobante: urlCompleta,
    cobro_id: cobroId,
    email_analista: emailAnalista
  }
};
